import React from 'react';

export const MatrixInput: React.FC<MatrixInputProps> = ({
                                                            n, matrix, vector, onChange
                                                        }) => {
    // ... те же обработчики

    return (
        <div className="space-y-6">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Матрица коэффициентов A:
                </label>
                <div className="overflow-x-auto border rounded-lg">
                    <table className="min-w-full divide-y divide-gray-200">
                        <tbody className="bg-white divide-y divide-gray-200">
                        {Array.from({ length: n }).map((_, i) => (
                            <tr key={i}>
                                {Array.from({ length: n }).map((_, j) => (
                                    <td key={j} className="px-1 py-1">
                                        <input
                                            type="number"
                                            value={getDisplayValue(matrix[i]?.[j] ?? 0)}
                                            onChange={(e) => handleMatrixChange(i, j, e.target.value)}
                                            className="w-20 px-2 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm"
                                            step="any"
                                            placeholder={`a${i+1}${j+1}`}
                                        />
                                    </td>
                                ))}
                            </tr>
                        ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Вектор правой части b:
                </label>
                <div className="overflow-x-auto border rounded-lg p-2">
                    <div className="flex flex-wrap gap-2">
                        {Array.from({ length: n }).map((_, i) => (
                            <div key={i} className="flex items-center">
                                <span className="text-xs text-gray-500 mr-1">b{i+1}=</span>
                                <input
                                    type="number"
                                    value={getDisplayValue(vector[i] ?? 0)}
                                    onChange={(e) => handleVectorChange(i, e.target.value)}
                                    className="w-20 px-2 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm"
                                    step="any"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};
